import {bmi as calculateBMI,trainingVolume} from './calculations.js';
const DB_NAME='fitos-local', DB_VERSION=1;
const TABLES=['profile','goals','measurements','exercises','plans','sessions','foods','meals','settings'];
const seedExercises=[
 ['胸推机','胸','固定器械','初级','双手握把，肩胛后收，推起时不要锁死肘关节。'],['杠铃卧推','胸','杠铃','中级','双脚踩稳，肩胛收紧，杠铃落至胸中部后推起。'],['哑铃上斜卧推','胸','哑铃','中级','凳面约 30°，控制哑铃下降并保持手腕中立。'],['绳索夹胸','胸','拉力器','初级','肘部微屈，双手在胸前汇合，感受胸肌收缩。'],['高位下拉','背','拉力器','初级','挺胸下拉至上胸，避免身体大幅后仰。'],['坐姿划船','背','固定器械','初级','躯干稳定，先收肩胛再拉肘，缓慢还原。'],['杠铃划船','背','杠铃','进阶','髋部后移保持背部中立，杠铃向下腹拉。'],['辅助引体向上','背','固定器械','中级','肩胛下沉后屈肘上拉，控制回到起始位置。'],['哑铃肩推','肩','哑铃','中级','核心收紧，哑铃从耳侧推至头顶上方。'],['哑铃侧平举','肩','哑铃','初级','手肘微屈，抬至肩高，避免借力耸肩。'],['面拉','肩','拉力器','初级','绳索拉向面部，肘部打开并外旋。'],['杠铃弯举','肱二头肌','杠铃','初级','上臂贴近身体，避免摆动借力。'],['绳索下压','肱三头肌','拉力器','初级','肘部固定在身体两侧，向下伸直手臂。'],['杠铃深蹲','股四头肌','杠铃','进阶','保持躯干稳定，膝盖随脚尖方向移动。'],['腿举机','股四头肌','固定器械','初级','脚掌踩稳踏板，下降至舒适深度后推起。'],['腿屈伸','股四头肌','固定器械','初级','调整轴心对齐膝关节，控制伸膝与回落。'],['罗马尼亚硬拉','腘绳肌','杠铃','中级','髋部向后折叠，杠铃贴近腿部，背部保持中立。'],['腿弯举','腘绳肌','固定器械','初级','屈膝发力并控制离心回程。'],['臀推','臀部','杠铃','中级','下巴微收，髋部伸展至身体成直线。'],['提踵','小腿','固定器械','初级','脚跟充分下降，再踮起并短暂停留。'],['平板支撑','腹部','自重','初级','身体保持直线，收紧腹部并正常呼吸。'],['跑步机快走','心肺','有氧设备','初级','按体能选择速度和坡度，循序渐进。'],['椭圆机','心肺','有氧设备','初级','保持稳定节奏，调整阻力至可持续强度。']
];
const seedFoods=[
 ['鸡蛋','143','12.6','0.7','9.5','USDA FoodData Central · 全蛋，熟'],['鸡胸肉','165','31','0','3.6','USDA FoodData Central · 烤制去皮'],['三文鱼','208','20.4','0','13.4','USDA FoodData Central · 熟'],['白米饭','130','2.7','28.2','0.3','USDA FoodData Central · 熟米饭'],['燕麦片','379','13.2','67.7','6.5','USDA FoodData Central · 干燕麦'],['香蕉','89','1.1','22.8','0.3','USDA FoodData Central · 生'],['西兰花','35','2.4','7.2','0.4','USDA FoodData Central · 熟'],['牛奶','61','3.2','4.8','3.3','USDA FoodData Central · 全脂'],['北豆腐','76','8.1','1.9','4.2','估算值 · 请以包装营养标签为准'],['红薯','90','2','20.7','0.2','USDA FoodData Central · 烤制'],['花生酱','588','25','20','50','USDA FoodData Central · 纯花生'],['希腊酸奶','97','9','3.9','5','USDA FoodData Central · 全脂原味']
];
const icons={home:'⌂',profile:'◎',body:'◉',goals:'◇',training:'↗',history:'◷',exercises:'▦',nutrition:'◒',foods:'◫',analysis:'⌁',ai:'✳',settings:'⚙'};
const nav=[['home','首页'],['profile','个人档案'],['body','身体记录'],['goals','目标管理'],['training','训练计划'],['history','训练历史'],['exercises','动作库'],['nutrition','饮食记录'],['foods','食物库'],['analysis','进度分析'],['ai','AI 私人教练'],['settings','设置']];
let db, page='home', activeSession=null, toastTimer;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=()=>crypto.randomUUID(); const today=()=>new Date().toLocaleDateString('en-CA'); const fmtDate=d=>d?new Date(`${d}T12:00:00`).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'—';
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{const d=req.result;for(const t of TABLES)if(!d.objectStoreNames.contains(t))d.createObjectStore(t,{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
const repo={all(table){return new Promise((res,rej)=>{const r=db.transaction(table).objectStore(table).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});},put(table,obj){return new Promise((res,rej)=>{obj.updatedAt=new Date().toISOString();const r=db.transaction(table,'readwrite').objectStore(table).put(obj);r.onsuccess=()=>res(obj);r.onerror=()=>rej(r.error);});},del(table,id){return new Promise((res,rej)=>{const r=db.transaction(table,'readwrite').objectStore(table).delete(id);r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});},clear(table){return new Promise((res,rej)=>{const r=db.transaction(table,'readwrite').objectStore(table).clear();r.onsuccess=()=>res();r.onerror=()=>rej(r.error);});}};
async function seed(){let ex=await repo.all('exercises');if(!ex.length)for(const [name,muscle,equipment,level,notes] of seedExercises)await repo.put('exercises',{id:uid(),name,muscle,equipment,level,notes,kind:equipment==='有氧设备'?'有氧运动':equipment==='自重'?'自重':'复合动作',sets:3,reps:'8–12'});let foods=await repo.all('foods');if(!foods.length)for(const [name,kcal,protein,carbs,fat,source] of seedFoods)await repo.put('foods',{id:uid(),name,kcal:+kcal,protein:+protein,carbs:+carbs,fat:+fat,source,custom:false});}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500);}
function navHTML(target){return nav.map(([id,label])=>`<a class="nav-link ${target===id?'active':''}" href="#${id}"><span class="nav-icon">${icons[id]}</span><span>${label}</span></a>`).join('');}
function navigate(){const next=location.hash.slice(1)||'home';page=nav.some(x=>x[0]===next)?next:'home';$('#side-nav').innerHTML=navHTML(page);$('#bottom-nav').innerHTML=['home','training','nutrition','analysis','settings'].map(id=>{const x=nav.find(v=>v[0]===id);return `<a class="nav-link ${page===id?'active':''}" href="#${id}"><span class="nav-icon">${icons[id]}</span><span>${x[1]}</span></a>`}).join('');$('#page-title').textContent=nav.find(v=>v[0]===page)?.[1]||'首页';$('#view').innerHTML='<div class="empty">正在加载…</div>';render().catch(e=>{console.error(e);$('#view').innerHTML=`<div class="banner">读取本地数据时发生错误：${esc(e.message)}。请刷新页面重试。</div>`;});}
function empty(title,copy,button=''){return `<div class="empty"><strong>${title}</strong>${copy}${button?`<div>${button}</div>`:''}</div>`}
function btn(text,action,primary=false,extra=''){const attrs=extra.startsWith('data-')?extra:'';const cls=attrs?'':extra;return `<button class="btn ${primary?'btn-primary':''} ${cls}" data-action="${action}" ${attrs}>${text}</button>`}
function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></div>`}
function formDialog(title,fields,submit,label='保存'){ $('#dialog-content').innerHTML=`<h2>${title}</h2><div class="field-grid">${fields}</div><div class="form-actions"><button class="btn" value="cancel">取消</button><button class="btn btn-primary" type="button" id="form-submit">${label}</button></div>`;$('#dialog').showModal();$('#form-submit').onclick=async()=>{const form=$('#dialog-content');if(!form.querySelector('input,select,textarea')?.closest('.field-grid').reportValidity?.()){}const data=Object.fromEntries(new FormData({...(form.querySelector('form')||{})}));}; }
function showForm(title,fields,onSave,label='保存'){const d=$('#dialog');$('#dialog-content').innerHTML=`<h2>${title}</h2><form id="edit-form"><div class="field-grid">${fields}</div><div class="form-actions"><button class="btn" type="button" data-close>取消</button><button class="btn btn-primary" type="submit">${label}</button></div></form>`;d.showModal();$('#edit-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{await onSave(data);d.close();toast('已保存');navigate();}catch(err){toast(`保存失败：${err.message}`);}};$$('[data-close]').forEach(b=>b.onclick=()=>d.close());}
const sectionHead=(title,sub,action='')=>`<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
const cardHeading=(title,right='')=>`<div class="card-heading"><h3>${title}</h3>${right}</div>`;
const metricBar=(label,val,goal)=>{const pct=goal?Math.max(0,Math.min(100,val/goal*100)):0;return `<div><div class="macro-head"><span>${label}</span><b>${Math.round(val)} / ${goal||'—'} g</b></div><div class="progress"><i style="width:${pct}%"></i></div></div>`;};
const num=(v,d=0)=>Number.isFinite(+v)?(+v).toFixed(d):'—';
async function render(){const f={home:homePage,profile:profilePage,body:bodyPage,goals:goalsPage,training:trainingPage,history:historyPage,exercises:exercisesPage,nutrition:nutritionPage,foods:foodsPage,analysis:analysisPage,ai:aiPage,settings:settingsPage};$('#today-date').textContent=fmtDate(today());$('#view').innerHTML=await f[page]();bindActions();if(page==='training'&&activeSession){window.currentSession=await getActive();if(window.currentSession?.restEndsAt){const card=document.createElement('article');card.className='card section';card.id='rest-card';card.innerHTML=`<div class="card-heading"><h3>组间休息</h3><button class="btn" id="stop-rest">跳过休息</button></div><div class="timer" id="rest-timer">00:00</div>`;$('#view').querySelector('.two-grid')?.after(card);$('#stop-rest').onclick=async()=>{const s=await getActive();s.restEndsAt=null;await repo.put('sessions',s);navigate();};}clearInterval(window.fitosTimer);window.fitosTimer=setInterval(()=>{const t=$('#session-timer');if(t)t.textContent=elapsed(window.currentSession);const rest=$('#rest-timer');if(rest){const left=Math.max(0,Math.ceil((window.currentSession.restEndsAt-Date.now())/1000));rest.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(!left){window.currentSession.restEndsAt=null;repo.put('sessions',window.currentSession);$('#rest-card')?.remove();}}},1000);}else clearInterval(window.fitosTimer);}
async function homePage(){const [profiles,goals,measurements,plans,sessions,meals,foods,settings]=await Promise.all(['profile','goals','measurements','plans','sessions','meals','foods','settings'].map(t=>repo.all(t)));const profile=profiles[0],goal=goals.find(g=>g.status==='active'),latest=[...measurements].sort((a,b)=>b.date.localeCompare(a.date))[0],plan=plans.find(p=>p.status==='active'),todayMeals=meals.filter(m=>m.date===today()),sum=todayMeals.reduce((s,m)=>{const f=foods.find(x=>x.id===m.foodId);if(f){const k=m.grams/100;s.kcal+=f.kcal*k;s.protein+=f.protein*k;s.carbs+=f.carbs*k;s.fat+=f.fat*k;}return s;},{kcal:0,protein:0,carbs:0,fat:0}),target=goal?.nutrition||settings.find(x=>x.id==='nutrition-target')||{};const thisWeek=sessions.filter(s=>s.status==='completed'&&((Date.now()-new Date(`${s.date}T12:00:00`).getTime())<7*864e5)).length;return `<div class="hero"><div><div class="hero-date">${fmtDate(today())} · DAILY OVERVIEW</div><h2>${profile?.nickname?`欢迎回来，${esc(profile.nickname)}`:'今天，开始照顾好自己'}</h2><p>${goal?`当前目标：${esc(goal.name)} · ${esc(goal.phase||'执行阶段')}`:'建立个人档案并设定目标，让计划更贴合你。'}</p></div>${!profile?btn('建立个人档案 →','profile',true):''}</div><div class="grid stats-grid"><article class="card stat"><div class="kicker">最新体重 <span>身体</span></div><div class="stat-value">${latest?.weight??'—'} <small>kg</small></div><div class="stat-foot">${latest?fmtDate(latest.date):'记录第一次身体数据'}</div><span class="stat-mark">↗</span></article><article class="card stat"><div class="kicker">本周训练 <span>训练</span></div><div class="stat-value">${thisWeek} <small>次</small></div><div class="stat-foot">来自已完成训练记录</div><span class="stat-mark">◷</span></article><article class="card stat"><div class="kicker">今日摄入 <span>营养</span></div><div class="stat-value">${Math.round(sum.kcal)} <small>${target.kcal?`/ ${target.kcal} kcal`:'kcal · 未设目标'}</small></div><div class="stat-foot">${todayMeals.length?'根据已记录食物计算':'今天尚未记录饮食'}</div><span class="stat-mark">◒</span></article><article class="card stat"><div class="kicker">当前计划 <span>计划</span></div><div class="stat-value" style="font-size:20px">${plan?esc(plan.name):'未设置'}</div><div class="stat-foot">${plan?`${plan.days.length} 个训练日`:'创建计划开始训练'}</div><span class="stat-mark">◇</span></article></div><div class="grid two-grid"><article class="card workout-card">${cardHeading('TODAY’S WORKOUT',plan?'计划就绪':'从计划开始')}${plan?`<div class="workout-meta"><span class="chip">${plan.days.length} 个训练日</span><span class="chip">约 ${plan.duration||60} 分钟</span></div><h3>${esc(plan.name)}</h3><p>训练记录会自动保存到本设备。</p>${btn(activeSession?'继续训练 →':'开始训练 →','start-workout',true)}`:empty('准备好开始了吗？','创建一份训练计划，记录每次训练。',btn('创建训练计划 →','new-plan',true))}</article><article class="card">${cardHeading('今日营养进度',todayMeals.length?'已记录':'未记录')}${todayMeals.length?target.kcal?`<div class="ring-row"><div class="ring" style="--pct:${Math.min(100,sum.kcal/target.kcal*100)}"><div class="ring-label">${Math.round(sum.kcal)}<small>kcal</small></div></div><div class="macro-list">${metricBar('蛋白质',sum.protein,target.protein)}${metricBar('碳水',sum.carbs,target.carbs)}${metricBar('脂肪',sum.fat,target.fat)}</div></div>`:`<p class="muted">今日 ${Math.round(sum.kcal)} kcal；尚未设置营养目标。</p>`:empty('饮食尚未记录','记录实际吃过的食物，查看营养摄入。',btn('记录饮食 →','quick-meal',true))}</article></div><div class="grid two-grid section"><article class="card">${cardHeading('最近训练记录',`<a href="#history" class="muted">查看全部 →</a>`)}${sessions.length?`<div class="list">${[...sessions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(s=>`<div class="list-row"><div class="row-main"><span class="row-icon">↗</span><div><div class="row-title">${esc(s.name)}</div><div class="row-sub">${fmtDate(s.date)} · ${s.exerciseCount||0} 个动作</div></div></div><span class="pill">${s.status==='completed'?'已完成':'进行中'}</span></div>`).join('')}</div>`:empty('还没有训练记录','完成第一次训练后，记录会显示在这里。')}</article><article class="card">${cardHeading('AI 今日建议','基于可用数据')}${goal?`<p style="font-size:12px;line-height:1.8;color:var(--muted)">${latest?'你已记录身体数据。持续在相近条件下记录体重，使用周平均观察趋势。':'补充一次身体记录，之后可以观察长期趋势。'}${sessions.length?' 保持规律训练，并记录每次训练的重量与次数。':''}</p>`:empty('建议从基础记录开始','填写档案、设定目标，再逐步记录训练与饮食。',btn('查看私人教练 →','ai'))}</article></div>`;}
async function profilePage(){const p=(await repo.all('profile'))[0]||{};const bmiValue=calculateBMI(p.weight,p.height),bmi=bmiValue?bmiValue.toFixed(1):null;return `<div class="hero"><div><div class="hero-date">YOUR PROFILE</div><h2>了解你的起点</h2><p>按需填写，信息保存在本设备。</p></div>${btn(p.id?'编辑档案':'建立档案','edit-profile',true)}</div>${p.id?`<div class="grid stats-grid"><div class="card stat"><div class="kicker">身高</div><div class="stat-value">${p.height||'—'} <small>cm</small></div></div><div class="card stat"><div class="kicker">档案体重</div><div class="stat-value">${p.weight||'—'} <small>kg</small></div></div><div class="card stat"><div class="kicker">BMI 估算</div><div class="stat-value">${bmi||'—'}</div><div class="stat-foot">仅供参考，不用于诊断</div></div><div class="card stat"><div class="kicker">训练经验</div><div class="stat-value" style="font-size:20px">${esc(p.experience||'未填写')}</div></div></div><article class="card section">${cardHeading('个人与训练偏好')}<div class="grid three-grid"><div><span class="muted">昵称</span><p>${esc(p.nickname||'未填写')}</p></div><div><span class="muted">目标</span><p>${esc(p.goalType||'未设置')}</p></div><div><span class="muted">每周训练</span><p>${p.frequency||'—'} 天</p></div><div><span class="muted">饮食偏好</span><p>${esc(p.preference||'未填写')}</p></div><div><span class="muted">过敏信息</span><p>${esc(p.allergies||'无')}</p></div><div><span class="muted">训练限制</span><p>${esc(p.limits||'无')}</p></div></div></article>`:empty('你的身体与训练档案','昵称、身高等非必要字段可以跳过。',btn('开始填写 →','edit-profile',true))}`;}
async function bodyPage(){const rows=(await repo.all('measurements')).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="hero"><div><div class="hero-date">BODY METRICS</div><h2>每次记录，都是进度的一部分</h2><p>体重和围度以公制单位保存；不记录的项目不会当作 0。</p></div>${btn('+ 新增记录','add-measurement',true)}</div>${rows.length?`<div class="grid stats-grid">${['weight','bodyFat','waist','chest'].map((k,i)=>{const x=rows.find(r=>r[k]!=null);return `<article class="card stat"><div class="kicker">${['最新体重','体脂率','腰围','胸围'][i]}</div><div class="stat-value">${x?x[k]:'—'} <small>${i===1?'%':i===0?'kg':'cm'}</small></div><div class="stat-foot">${x?fmtDate(x.date):'暂无记录'}</div></article>`}).join('')}</div><article class="card section">${cardHeading('记录历史',`${rows.length} 条记录`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>体重 kg</th><th>体脂 %</th><th>腰围 cm</th><th>臀围 cm</th><th>备注</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${r.weight??'—'}</td><td>${r.bodyFat??'—'}</td><td>${r.waist??'—'}</td><td>${r.hip??'—'}</td><td>${esc(r.note||'—')}</td><td class="table-actions"><button class="btn btn-quiet" data-action="edit-measurement" data-id="${r.id}">编辑</button></td></tr>`).join('')}</tbody></table></div></article>`:empty('还没有身体数据','记录体重、围度或体脂率，之后可以查看真实变化。',btn('记录第一次数据 →','add-measurement',true))}`;}
async function goalsPage(){const goals=(await repo.all('goals')).sort((a,b)=>b.updatedAt?.localeCompare(a.updatedAt)||0);return `<div class="hero"><div><div class="hero-date">YOUR GOALS</div><h2>目标清楚，进度可见</h2><p>每类目标使用相应指标；设定目标不代表预测一定达成。</p></div>${btn('+ 新建目标','add-goal',true)}</div><div class="grid two-grid">${goals.length?goals.map(g=>`<article class="card">${cardHeading(esc(g.name),`<span class="pill">${esc(g.status)}</span>`)}<div class="kicker">${esc(g.type)} · ${esc(g.phase||'执行阶段')}</div><p style="font-size:18px;margin:15px 0">${g.current??'—'} → ${g.target??'—'} <small class="muted">${esc(g.unit||'')}</small></p><p class="muted" style="font-size:11px">${fmtDate(g.startDate)}${g.targetDate?' — '+fmtDate(g.targetDate):''}</p><p style="font-size:11px;color:var(--muted)">${esc(g.note||'')}</p></article>`).join(''):empty('还没有目标','减脂、增肌、力量和体能目标都可分别管理。',btn('设定第一个目标 →','add-goal',true))}</div>`;}
async function trainingPage(){const [plans,exercises,sessions]=await Promise.all(['plans','exercises','sessions'].map(t=>repo.all(t)));const p=plans.find(x=>x.status==='active');if(activeSession){const s=sessions.find(x=>x.id===activeSession.id);return `<div class="hero"><div><div class="hero-date">WORKOUT IN PROGRESS · 自动保存</div><h2>${esc(s?.name||activeSession.name)}</h2><p>${fmtDate(s?.date||today())} · 关闭页面后可继续本次训练</p></div>${btn('结束训练','finish-workout',true)}</div><div class="grid two-grid"><article class="card">${cardHeading('训练计时',s?.paused?'已暂停':'进行中')}<div class="timer" id="session-timer">${elapsed(s)}</div><p class="muted" style="font-size:11px">已用时</p>${btn(s?.paused?'继续':'暂停训练','pause-workout')}</article><article class="card">${cardHeading('训练概况')}<div class="grid three-grid"><div><div class="kicker">动作</div><p>${s?.exercises?.length||0}</p></div><div><div class="kicker">已完成组</div><p>${s?.exercises?.flatMap(x=>x.sets).filter(x=>x.done).length||0}</p></div><div><div class="kicker">训练容量</div><p>${volume(s)} kg</p></div></div></article></div>${(s?.exercises||[]).map((x,xi)=>`<article class="card session-exercise"><div class="card-heading"><div><h3>${esc(x.name)}</h3><small>${x.targetSets} 组 · ${x.targetReps} 次 · 目标休息 ${x.rest}s</small></div><button class="btn" data-action="skip-exercise" data-index="${xi}">跳过动作</button></div><div class="set-grid">${x.sets.map((z,si)=>`<div class="set-box ${z.done?'done':''}">${z.done?'✓ ':''}${si+1} · ${z.weight??'自重'}kg × ${z.reps??x.targetReps}</div>`).join('')}</div><div class="toolbar" style="margin-top:12px">${btn('+ 完成一组','complete-set',true,`data-index="${xi}"`)}${btn('替换动作','replace-exercise',false,`data-index="${xi}"`)}</div></article>`).join('')}`;}
return `<div class="hero"><div><div class="hero-date">TRAINING PLAN</div><h2>计划为你服务，不是限制</h2><p>调整动作、组数和次数；历史训练保存独立快照。</p></div>${btn('+ 创建计划','new-plan',true)}</div>${p?`<article class="card">${cardHeading(esc(p.name),`${p.days.length} 个训练日`)}<div class="grid three-grid">${p.days.map((d,di)=>`<div class="card" style="padding:14px;background:var(--panel2)"><div class="card-heading"><h3>${esc(d.name)}</h3><button class="btn btn-quiet" data-action="edit-plan-day" data-index="${di}">编辑</button></div><div class="list">${d.exercises.map(id=>{const e=exercises.find(x=>x.id===id);return `<div class="list-row"><span class="row-title">${esc(e?.name||'已删除动作')}</span><span class="row-sub">${e?.sets||3} × ${e?.reps||'8–12'}</span></div>`}).join('')}</div></div>`).join('')}</div><div class="form-actions">${btn('归档计划','archive-plan',false,'btn-danger')}${btn('开始训练 →','start-workout',true)}</div></article>`:empty('还没有训练计划','从内置动作库挑选动作，创建适合自己的训练安排。',btn('创建训练计划 →','new-plan',true))}${sectionHead('训练偏好','计划可随时调整')}</>`;}
function elapsed(s){let seconds=s?.elapsed||0;if(s&&!s.paused&&s.startedAt)seconds+=Math.floor((Date.now()-new Date(s.startedAt).getTime())/1000);return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds%3600/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function volume(s){return Math.round(trainingVolume(s?.exercises));}
async function historyPage(){const rows=(await repo.all('sessions')).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="hero"><div><div class="hero-date">WORKOUT HISTORY</div><h2>每次训练，留下可用的数据</h2><p>训练组快照不会随计划修改而改变。</p></div></div>${rows.length?`<article class="card">${cardHeading('训练历史',`${rows.length} 条记录`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>训练</th><th>动作数</th><th>完成组</th><th>训练容量</th><th>状态</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${fmtDate(s.date)}</td><td>${esc(s.name)}</td><td>${s.exerciseCount||s.exercises?.length||0}</td><td>${s.exercises?.flatMap(x=>x.sets).filter(x=>x.done).length||0}</td><td>${volume(s)} kg</td><td>${s.status==='completed'?'已完成':'进行中'}</td></tr>`).join('')}</tbody></table></div></article>`:empty('还没有训练历史','训练完成后，日期、动作、组数和容量会保存在这里。')}`;}
async function exercisesPage(){const rows=await repo.all('exercises');return `<div class="hero"><div><div class="hero-date">GYM EXERCISE LIBRARY</div><h2>动作库 <span class="muted" style="font-size:14px">${rows.length} 个动作</span></h2><p>常用商业健身房动作，含简明技术提示。</p></div></div><div class="toolbar"><input id="exercise-search" placeholder="搜索动作或肌群"><select id="exercise-muscle"><option value="">全部肌群</option>${[...new Set(rows.map(x=>x.muscle))].map(m=>`<option>${esc(m)}</option>`).join('')}</select><select id="exercise-equipment"><option value="">全部器械</option>${[...new Set(rows.map(x=>x.equipment))].map(m=>`<option>${esc(m)}</option>`).join('')}</select></div><div class="grid three-grid section" id="exercise-list">${rows.map(x=>`<article class="card exercise-card" data-name="${esc(x.name+' '+x.muscle)}" data-muscle="${esc(x.muscle)}" data-equipment="${esc(x.equipment)}">${cardHeading(esc(x.name),`<span class="pill">${esc(x.level)}</span>`)}<div class="kicker">${esc(x.muscle)} · ${esc(x.equipment)}</div><p style="font-size:11px;line-height:1.7;color:var(--muted)">${esc(x.notes)}</p><span class="chip">参考 ${x.sets||3} 组 · ${x.reps||'8–12'} 次</span></article>`).join('')}</div>`;}
async function nutritionPage(){const [meals,foods,goals,settings]=await Promise.all(['meals','foods','goals','settings'].map(t=>repo.all(t)));const day=new URLSearchParams(location.hash.split('?')[1]||'').get('date')||today(),items=meals.filter(m=>m.date===day),tot=items.reduce((a,m)=>{const f=foods.find(x=>x.id===m.foodId);if(!f)return a;const r=m.grams/100;for(const k of ['kcal','protein','carbs','fat'])a[k]+=f[k]*r;return a;},{kcal:0,protein:0,carbs:0,fat:0}),g=goals.find(x=>x.status==='active'),target=g?.nutrition||settings.find(x=>x.id==='nutrition-target')||{kcal:2000,protein:130,carbs:220,fat:65},labels=['早餐','午餐','晚餐','加餐'];return `<div class="hero"><div><div class="hero-date">DAILY NUTRITION · ${fmtDate(day)}</div><h2>记录真实摄入，理解日常选择</h2><p>营养估算基于食物库每 100g 数据，包装食品优先参考标签。</p></div>${btn('+ 记录食物','add-meal',true)}</div><div class="grid stats-grid"><article class="card stat"><div class="kicker">热量摄入</div><div class="stat-value">${Math.round(tot.kcal)} <small>/ ${target.kcal} kcal</small></div><div class="stat-foot">剩余 ${Math.round(target.kcal-tot.kcal)} kcal · ${items.length?'已记录':'未记录'}</div></article>${[['蛋白质','protein'],['碳水','carbs'],['脂肪','fat']].map(([l,k])=>`<article class="card stat"><div class="kicker">${l}</div><div class="stat-value">${Math.round(tot[k])} <small>/ ${target[k]} g</small></div><div class="progress" style="margin-top:12px"><i style="width:${Math.min(100,tot[k]/target[k]*100)}%"></i></div><div class="stat-foot">差额 ${Math.round(target[k]-tot[k])} g</div></article>`).join('')}</div>${labels.map(meal=>{const list=items.filter(x=>x.meal===meal);return `<article class="card meal-group">${cardHeading(meal,btn('+ 添加','add-meal',false,`data-meal="${meal}"`))}${list.length?list.map(m=>{const f=foods.find(x=>x.id===m.foodId);return `<div class="meal-item"><span>${esc(f?.name||'食物已删除')} · ${m.grams} g</span><span>${f?Math.round(f.kcal*m.grams/100):'—'} kcal <button class="btn btn-quiet" data-action="delete-meal" data-id="${m.id}">删除</button></span></div>`}).join(''):empty('未记录','')}</article>`}).join('')}`;}
async function foodsPage(){const foods=await repo.all('foods');return `<div class="hero"><div><div class="hero-date">FOOD DATABASE</div><h2>常见食物营养库</h2><p>每 100g 数值；个别食材受品种、品牌和烹饪方式影响。</p></div>${btn('+ 自定义食物','add-food',true)}</div><div class="toolbar"><input id="food-search" placeholder="搜索食物"><select id="food-source"><option value="">全部来源</option><option value="custom">自定义</option><option value="ref">参考数据</option></select></div><article class="card section">${cardHeading('食物与营养数据',`${foods.length} 种`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>食物</th><th>热量 kcal</th><th>蛋白质 g</th><th>碳水 g</th><th>脂肪 g</th><th>数据说明</th></tr></thead><tbody id="food-table">${foods.map(f=>`<tr data-name="${esc(f.name)}" data-custom="${f.custom}"><td>${esc(f.name)}</td><td>${num(f.kcal,1)}</td><td>${num(f.protein,1)}</td><td>${num(f.carbs,1)}</td><td>${num(f.fat,1)}</td><td>${esc(f.source||'用户自定义')}</td></tr>`).join('')}</tbody></table></div></article>`;}
async function analysisPage(){const [measurements,sessions,meals,foods]=await Promise.all(['measurements','sessions','meals','foods'].map(t=>repo.all(t)));const data=measurements.filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date));const completed=sessions.filter(x=>x.status==='completed');const workoutWeeks=Array.from({length:8},(_,i)=>{const end=new Date();end.setDate(end.getDate()-((7-end.getDay())%7)-i*7);const start=new Date(end);start.setDate(start.getDate()-6);return {label:`${start.getMonth()+1}/${start.getDate()}`,n:completed.filter(s=>new Date(`${s.date}T12:00:00`)>=start&&new Date(`${s.date}T12:00:00`)<=end).length};}).reverse();const chart=data.length>1?lineChart(data.map(x=>({label:fmtDate(x.date).slice(5),value:+x.weight})),`${data[0].weight} – ${data.at(-1).weight} kg`):empty('数据还不够','至少记录两次体重后，才会显示真实趋势。');const kcalDays=new Map();for(const m of meals){const f=foods.find(x=>x.id===m.foodId);if(!f)continue;kcalDays.set(m.date,(kcalDays.get(m.date)||0)+f.kcal*m.grams/100);}return `<div class="hero"><div><div class="hero-date">PROGRESS & ANALYTICS</div><h2>观察趋势，做出适合自己的调整</h2><p>仅使用你实际保存的数据；缺少记录时不补造趋势。</p></div></div><div class="grid two-grid"><article class="card">${cardHeading('体重趋势',data.length?`${data.length} 次记录`:'暂无记录')}${data.length>1?chart:data.length===1?`<div class="empty">当前只有一次记录（${data[0].weight} kg）。继续记录以形成趋势。</div>`:empty('暂无体重数据','先在身体记录中添加测量。')}</article><article class="card">${cardHeading('训练频率','近 8 周')}${barChart(workoutWeeks)}<p class="muted" style="font-size:10px">仅统计已完成训练；每柱代表自然周。</p></article></div><div class="grid two-grid section"><article class="card">${cardHeading('训练数据',`${completed.length} 次已完成`)}${completed.length?`<p>总训练时长：${completed.reduce((a,s)=>a+(s.duration||0),0)} 分钟</p><p>累计训练容量：${completed.reduce((a,s)=>a+volume(s),0).toLocaleString()} kg</p>`:empty('训练历史不足','完成训练后可以分析频率和训练容量。')}</article><article class="card">${cardHeading('饮食记录完整度')}${kcalDays.size?`<p>有记录的日期：<b>${kcalDays.size}</b> 天</p><p>已记录日期的平均摄入：<b>${Math.round([...kcalDays.values()].reduce((a,b)=>a+b,0)/kcalDays.size)} kcal</b></p><p class="muted" style="font-size:10px">未记录日期已排除，不视为零摄入。</p>`:empty('还没有饮食记录','记录实际餐食后可以查看摄入汇总。')}</article></div>`;}
function lineChart(points,caption){const w=600,h=200,pad={l:38,r:15,t:14,b:25},vals=points.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;const coords=points.map((x,i)=>[pad.l+i*(w-pad.l-pad.r)/Math.max(1,points.length-1),pad.t+(max-x.value)*(h-pad.t-pad.b)/span]);const path=coords.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${caption}"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c3f36b" stop-opacity=".18"/><stop offset="1" stop-color="#c3f36b" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{let y=pad.t+i*(h-pad.t-pad.b)/3;return `<line x1="${pad.l}" y1="${y}" x2="${w-pad.r}" y2="${y}" class="grid-line"/><text x="0" y="${y+3}">${(max-i*span/3).toFixed(1)}</text>`}).join('')}<path d="${path} L${coords.at(-1)[0]} ${h-pad.b} L${coords[0][0]} ${h-pad.b} Z" class="area"/><path d="${path}" class="series"/>${coords.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="var(--lime)"><title>${points[i].label}: ${points[i].value} kg</title></circle>`).join('')}</svg></div>`;}
function barChart(points){const w=600,h=150,p=8,max=Math.max(1,...points.map(x=>x.n));return `<div class="chart"><svg viewBox="0 0 ${w} ${h}">${points.map((x,i)=>{const step=(w-20)/points.length,bw=step*.52,bh=(h-28)*x.n/max,y=h-25-bh,xx=10+step*i+(step-bw)/2;return `<rect x="${xx}" y="${y}" width="${bw}" height="${Math.max(2,bh)}" rx="4" fill="${x.n?'var(--lime)':'var(--line)'}"/><text x="${xx+bw/2}" y="${h-7}" text-anchor="middle">${x.label}</text><text x="${xx+bw/2}" y="${y-5}" text-anchor="middle">${x.n||''}</text>`}).join('')}</svg></div>`;}
async function aiPage(){const settings=(await repo.all('settings')).find(x=>x.id==='ai');return `<div class="hero"><div><div class="hero-date">AI PERSONAL COACH</div><h2>AI 是辅助工具，事实来自你的记录</h2><p>未配置服务时，FitOS 的训练、饮食、记录和统计仍可使用。</p></div></div><div class="banner"><strong>隐私说明</strong>：使用 AI 时，你明确发起的请求会把必要上下文发送给所选服务商。不要发送不必要的身份信息。浏览器直连会让 API Key 暴露在当前浏览器环境，并受服务商跨域策略限制；本地保存不等于安全保密。</div><article class="card section">${cardHeading('兼容 OpenAI Chat Completions 的服务配置',settings?'已配置':'未配置')}<form id="ai-form"><div class="field-grid">${field('服务商名称','provider',settings?.provider||'自定义服务商')}${field('API Base URL','baseUrl',settings?.baseUrl||'https://api.openai.com/v1','url')}${field('模型名称','model',settings?.model||'')}${field('API Key（仅会话保存）','apiKey','','password','autocomplete="off" placeholder="留空仅测试已填写密钥"')}<div class="field field-wide"><label><input type="checkbox" name="consent" style="width:auto" required> 我了解请求会发送至所配置服务商，也了解浏览器直连的密钥风险。</label></div></div><div class="form-actions"><button type="button" class="btn" data-action="test-ai">测试连接</button><button type="submit" class="btn btn-primary">保存配置</button></div></form></article><div class="grid three-grid section">${[['训练计划建议','coach-plan'],['饮食方案建议','coach-meal'],['每周复盘','coach-review']].map(([t,a])=>`<article class="card">${cardHeading(t)}<p class="muted" style="font-size:11px;line-height:1.7">使用真实档案和记录形成建议；输出需要你确认，不会自动改动计划和历史数据。</p>${btn('生成建议 →',a)}</article>`).join('')}</div><article class="card section">${cardHeading('最近 AI 建议')}<div id="ai-output">${settings?empty('尚未生成建议','选择上方功能生成建议预览。'):empty('还没有配置 AI 服务','填写服务商、模型并测试连接。')}</div></article>`;}
async function settingsPage(){const s=(await repo.all('settings')).find(x=>x.id==='nutrition-target')||{kcal:2000,protein:130,carbs:220,fat:65};return `<div class="hero"><div><div class="hero-date">SETTINGS & PRIVACY</div><h2>数据由你掌控</h2><p>本地存储没有账号隔离或跨设备同步。</p></div></div><article class="card">${cardHeading('本地数据说明')}<div class="banner">当前版本的数据保存在本设备的浏览器中。清理浏览器数据、使用其他设备或更换浏览器时，记录不会自动同步，请定期导出备份。设备上的其他使用者可能访问本地记录。</div></article><div class="grid two-grid section"><article class="card">${cardHeading('每日营养目标','用户手动设置优先')}<form id="target-form"><div class="field-grid">${field('热量 kcal','kcal',s.kcal,'number','min="0" required')}${field('蛋白质 g','protein',s.protein,'number','min="0" required')}${field('碳水 g','carbs',s.carbs,'number','min="0" required')}${field('脂肪 g','fat',s.fat,'number','min="0" required')}</div><div class="form-actions"><button class="btn btn-primary">保存目标</button></div></form></article><article class="card">${cardHeading('数据备份与恢复')}<p class="muted" style="font-size:11px;line-height:1.8">JSON 备份包含 FitOS 业务记录，不包含 AI 密钥或二进制照片。</p><div class="toolbar">${btn('导出完整 JSON','backup',true)}${btn('恢复 / 合并 JSON','restore')}${btn('导出 CSV','csv-export')}</div><div class="settings-row"><h3>清空全部 FitOS 数据</h3><p>此操作不可撤销。建议先下载 JSON 备份。</p>${btn('清空数据','clear-data',false,'btn-danger')}</div></article></div><div class="section"><div class="kicker">DISPLAY</div><div class="toolbar section">${btn('切换深色 / 浅色主题','theme')}</div></div>`;}
function collectForm(form){return Object.fromEntries(new FormData(form));}
function bindActions(){
 $$('#view [data-action]').forEach(b=>b.onclick=()=>actions(b.dataset.action,b));
 const exSearch=$('#exercise-search');if(exSearch)exSearch.oninput=filterExercises;
 $('#exercise-muscle')?.addEventListener('change',filterExercises);$('#exercise-equipment')?.addEventListener('change',filterExercises);
 $('#food-search')?.addEventListener('input',filterFoods);$('#food-source')?.addEventListener('change',filterFoods);
 $('#target-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=collectForm(e.currentTarget);await repo.put('settings',{id:'nutrition-target',kcal:+d.kcal,protein:+d.protein,carbs:+d.carbs,fat:+d.fat});toast('营养目标已保存');});
 $('#ai-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=collectForm(e.currentTarget);sessionStorage.setItem('fitos-ai-key',d.apiKey||sessionStorage.getItem('fitos-ai-key')||'');await repo.put('settings',{id:'ai',provider:d.provider,baseUrl:d.baseUrl.replace(/\/$/,''),model:d.model});toast('AI 服务配置已保存（密钥仅在此标签页会话保存）');navigate();});
}
function filterExercises(){const q=$('#exercise-search').value.toLowerCase(),m=$('#exercise-muscle').value,e=$('#exercise-equipment').value;$$('.exercise-card').forEach(c=>c.hidden=!(c.dataset.name.toLowerCase().includes(q)&&(!m||c.dataset.muscle===m)&&(!e||c.dataset.equipment===e)));}
function filterFoods(){const q=$('#food-search').value.toLowerCase(),s=$('#food-source').value;$$('#food-table tr').forEach(r=>r.hidden=!(r.dataset.name.toLowerCase().includes(q)&&(!s||(s==='custom'?r.dataset.custom==='true':r.dataset.custom!=='true'))));}
async function actions(a,b){try{switch(a){case'edit-profile':return editProfile();case'add-measurement':return editMeasurement();case'edit-measurement':return editMeasurement(await repo.all('measurements').then(x=>x.find(z=>z.id===b.dataset.id)));case'add-goal':return editGoal();case'new-plan':return editPlan();case'edit-plan-day':return editPlanDay(+b.dataset.index);case'archive-plan':{if(!confirm('归档当前计划？已完成训练历史会保留。'))return;const p=(await repo.all('plans')).find(x=>x.status==='active');if(p){p.status='archived';await repo.put('plans',p);}return navigate();}case'start-workout':return startWorkout();case'complete-set':return completeSet(+b.dataset.index);case'skip-exercise':return skipExercise(+b.dataset.index);case'replace-exercise':return replaceExercise(+b.dataset.index);case'finish-workout':return finishWorkout();case'pause-workout':return pauseWorkout();case'add-meal':return editMeal(null,b.dataset.meal);case'delete-meal':if(confirm('删除这条饮食记录？')){await repo.del('meals',b.dataset.id);return navigate();}break;case'add-food':return editFood();case'quick-meal':location.hash='#nutrition';setTimeout(()=>actions('add-meal',{}),100);return;case'backup':return backup();case'restore':$('#restore-file').click();return;case'csv-export':return csvMenu();case'clear-data':return clearData();case'theme':return toggleTheme();case'test-ai':return testAI();case'coach-plan':case'coach-meal':case'coach-review':return aiSuggestion(a);default:if(nav.some(x=>x[0]===a)){location.hash=`#${a}`;return;}}}
catch(e){toast(`操作失败：${e.message}`);}}
function editProfile(p={}){const fields=field('昵称','nickname',p.nickname||'')+field('出生日期（可选）','birthDate',p.birthDate||'','date')+field('性别参数（可选）','sex',p.sex||'','text','placeholder="用于估算公式；可留空"')+field('身高 cm','height',p.height||'','number','min="100" max="250"')+field('当前体重 kg','weight',p.weight||'','number','min="25" max="350" step="0.1"')+`<div class="field"><label>健身经验</label><select name="experience"><option>${esc(p.experience||'新手')}</option>${['新手','有一定经验','进阶'].filter(x=>x!==p.experience).map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>目标类型</label><select name="goalType">${['减脂','减重','增肌','减脂增肌','力量提升','体能提升','自定义'].map(x=>`<option ${p.goalType===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('每周训练天数','frequency',p.frequency||3,'number','min="1" max="7"')}${field('日常活动水平','activity',p.activity||'','text','placeholder="久坐、轻体力等，可选"')}${field('饮食偏好','preference',p.preference||'')}${field('过敏信息','allergies',p.allergies||'')}${field('训练限制或不适','limits',p.limits||'')}`;showForm('个人档案',fields,async d=>{await repo.put('profile',{...p,id:p.id||uid(),...d,height:d.height?+d.height:null,weight:d.weight?+d.weight:null,frequency:d.frequency?+d.frequency:3});});}
function editMeasurement(r={}){const fields=field('日期','date',r.date||today(),'date','required')+field('体重 kg','weight',r.weight??'','number','min="25" max="350" step="0.1"')+field('体脂率 %','bodyFat',r.bodyFat??'','number','min="1" max="75" step="0.1"')+field('腰围 cm','waist',r.waist??'','number','min="1" max="250" step="0.1"')+field('臀围 cm','hip',r.hip??'','number','min="1" max="250" step="0.1"')+field('胸围 cm','chest',r.chest??'','number','min="1" max="250" step="0.1"')+field('左臂围 cm','arm',r.arm??'','number','min="1" max="100" step="0.1"')+field('左大腿围 cm','thigh',r.thigh??'','number','min="1" max="150" step="0.1"')+`<div class="field field-wide"><label>备注</label><input name="note" value="${esc(r.note||'')}"></div>`;showForm(r.id?'编辑身体记录':'添加身体记录',fields,async d=>{const vals={};for(const k of ['weight','bodyFat','waist','hip','chest','arm','thigh'])if(d[k]!=='')vals[k]=+d[k];await repo.put('measurements',{...r,id:r.id||uid(),date:d.date,...vals,note:d.note||''});});}
function editGoal(){const fields=field('目标名称','name','','text','required')+`<div class="field"><label>目标类型</label><select name="type">${['减脂','减重','增肌','减脂增肌','力量提升','体能提升','自定义'].map(x=>`<option>${x}</option>`).join('')}</select></div>`+field('当前值','current','','number','step="0.1"')+field('目标值','target','','number','step="0.1"')+field('单位','unit','kg')+field('开始日期','startDate',today(),'date','required')+field('目标日期（可选）','targetDate','','date')+field('当前阶段','phase','执行阶段')+field('每日热量目标 kcal','kcal','2000','number','min="0"')+field('蛋白质目标 g','protein','130','number','min="0"')+field('碳水目标 g','carbs','220','number','min="0"')+field('脂肪目标 g','fat','65','number','min="0"')+`<div class="field field-wide"><label>备注</label><input name="note"></div>`;showForm('创建健身目标',fields,async d=>{const g={id:uid(),...d,current:d.current===''?null:+d.current,target:d.target===''?null:+d.target,nutrition:{kcal:+d.kcal,protein:+d.protein,carbs:+d.carbs,fat:+d.fat},status:'active'};for(const old of await repo.all('goals'))if(old.status==='active'){old.status='archived';await repo.put('goals',old);}await repo.put('goals',g);});}
async function editPlan(){const ex=await repo.all('exercises');if(!ex.length)return toast('动作库暂时为空');const choices=ex.map(x=>`<label class="list-row" style="justify-content:flex-start;gap:8px"><input type="checkbox" name="exercise" value="${x.id}" style="width:auto"><span class="row-title">${esc(x.name)}</span><span class="row-sub">${esc(x.muscle)}</span></label>`).join('');const f=`<div class="field field-wide"><label>计划名称</label><input name="name" required value="全身基础计划"></div><div class="field"><label>预计时长（分钟）</label><input type="number" name="duration" value="60" min="10" max="300"></div><div class="field field-wide"><label>选择首个训练日的动作</label><div style="max-height:240px;overflow:auto">${choices}</div></div>`;showForm('创建训练计划',f,async d=>{const ids=[...$('#edit-form').querySelectorAll('[name=exercise]:checked')].map(x=>x.value);if(!ids.length)throw new Error('至少选择一个动作');await repo.put('plans',{id:uid(),name:d.name,duration:+d.duration||60,status:'active',days:[{id:uid(),name:'训练日 A',exercises:ids}],createdAt:new Date().toISOString(),version:1});});}
async function editPlanDay(index){const plans=await repo.all('plans'),p=plans.find(x=>x.status==='active'),ex=await repo.all('exercises');if(!p)return;const d=p.days[index];const fields=`<div class="field field-wide"><label>训练日名称</label><input name="name" value="${esc(d.name)}" required></div><div class="field field-wide"><label>动作（取消勾选即可移除）</label><div style="max-height:300px;overflow:auto">${ex.map(x=>`<label class="list-row" style="justify-content:flex-start;gap:8px"><input type="checkbox" name="exercise" value="${x.id}" ${d.exercises.includes(x.id)?'checked':''} style="width:auto"><span class="row-title">${esc(x.name)}</span><span class="row-sub">${esc(x.muscle)}</span></label>`).join('')}</div></div>`;showForm('编辑训练日',fields,async val=>{const ids=[...$('#edit-form').querySelectorAll('[name=exercise]:checked')].map(x=>x.value);if(!ids.length)throw new Error('训练日至少保留一个动作');const copy=structuredClone(p);copy.version=(copy.version||1)+1;copy.days[index]={...d,name:val.name,exercises:ids};await repo.put('plans',copy);});}
async function startWorkout(){const sessions=await repo.all('sessions');const existing=sessions.find(x=>x.status==='in-progress');if(existing){activeSession={id:existing.id};location.hash='#training';return navigate();}const [plans,exercises]=await Promise.all(['plans','exercises'].map(t=>repo.all(t)));const plan=plans.find(x=>x.status==='active');if(!plan)return toast('请先创建训练计划');const day=plan.days[0];const snap=day.exercises.map(id=>{const e=exercises.find(x=>x.id===id);return {exerciseId:id,name:e.name,muscle:e.muscle,targetSets:e.sets||3,targetReps:e.reps||'8–12',rest:90,sets:[],skipped:false};});const s={id:uid(),planId:plan.id,planVersion:plan.version||1,name:`${plan.name} · ${day.name}`,date:today(),status:'in-progress',startedAt:new Date().toISOString(),elapsed:0,paused:false,exercises:snap,exerciseCount:snap.length};await repo.put('sessions',s);activeSession={id:s.id};location.hash='#training';navigate();}
async function getActive(){const ss=await repo.all('sessions');return ss.find(x=>x.id===activeSession?.id)||ss.find(x=>x.status==='in-progress');}
async function completeSet(i){const s=await getActive();if(!s)return;const x=s.exercises[i];const previous=await repo.all('sessions');const prior=previous.filter(z=>z.status==='completed').flatMap(z=>z.exercises||[]).filter(y=>y.exerciseId===x.exerciseId).flatMap(y=>y.sets||[]).filter(y=>y.done);const last=prior.at(-1);const fields=field('重量 kg（自重可留空）','weight',last?.weight??'','number','min="0" step="0.5"')+field('完成次数','reps',String(parseInt(x.targetReps)||8),'number','min="1" max="100" required')+`<div class="field"><label>组类型</label><select name="type"><option>正式组</option><option>热身组</option><option>递减组</option></select></div>`+field('RPE（可选）','rpe','','number','min="1" max="10" step="0.5"');showForm(`完成第 ${x.sets.length+1} 组 · ${x.name}`,fields,async d=>{x.sets.push({id:uid(),type:d.type,weight:d.weight===''?null:+d.weight,reps:+d.reps,rpe:d.rpe?+d.rpe:null,done:true,recordedAt:new Date().toISOString()});s.exerciseCount=s.exercises.filter(e=>!e.skipped).length;s.restEndsAt=Date.now()+x.rest*1000;await repo.put('sessions',s);});}
async function skipExercise(i){const s=await getActive();if(!s)return;s.exercises[i].skipped=true;await repo.put('sessions',s);navigate();}
async function replaceExercise(i){const s=await getActive(),all=await repo.all('exercises');const current=s.exercises[i];const candidates=all.filter(x=>x.muscle===current.muscle);const fields=`<div class="field field-wide"><label>替换为</label><select name="id">${candidates.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.equipment)}</option>`).join('')}</select></div>`;showForm('替换动作',fields,async d=>{const ex=all.find(x=>x.id===d.id);s.exercises[i]={...s.exercises[i],exerciseId:ex.id,name:ex.name,muscle:ex.muscle,sets:[]};await repo.put('sessions',s);});}
async function pauseWorkout(){const s=await getActive();if(!s)return;if(s.paused){s.paused=false;s.startedAt=new Date().toISOString();}else{s.elapsed=(s.elapsed||0)+Math.floor((Date.now()-new Date(s.startedAt).getTime())/1000);s.paused=true;s.startedAt=null;}await repo.put('sessions',s);navigate();}
async function finishWorkout(){const s=await getActive();if(!s)return;if(!s.paused)s.elapsed=(s.elapsed||0)+Math.floor((Date.now()-new Date(s.startedAt).getTime())/1000);const n=s.exercises.flatMap(x=>x.sets).filter(x=>x.done).length;if(!n&&!confirm('这次训练还没有完成训练组。仍要结束并保存吗？'))return;s.status='completed';s.duration=Math.round(s.elapsed/60);s.endedAt=new Date().toISOString();s.startedAt=null;s.exerciseCount=s.exercises.filter(x=>x.sets.length>0&&!x.skipped).length;await repo.put('sessions',s);activeSession=null;toast(`训练已保存 · ${n} 组 · ${s.duration} 分钟`);navigate();}
async function editMeal(record=null,meal='加餐'){const [foods,meals]=await Promise.all(['foods','meals'].map(t=>repo.all(t)));if(!foods.length)return toast('食物库为空，请先添加食物');const fields=`<div class="field"><label>餐次</label><select name="meal">${['早餐','午餐','晚餐','加餐'].map(x=>`<option ${meal===x||record?.meal===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>食物</label><select name="foodId">${foods.map(x=>`<option value="${x.id}" ${record?.foodId===x.id?'selected':''}>${esc(x.name)} · ${x.kcal} kcal/100g</option>`).join('')}</select></div>${field('重量 g','grams',record?.grams||100,'number','min="1" max="5000" step="1" required')}${field('日期','date',record?.date||today(),'date','required')}<div class="field field-wide"><label>可复用最近餐食</label><select id="reuse-meal"><option value="">不复用</option>${meals.slice(-25).reverse().map(m=>`<option value="${m.id}">${fmtDate(m.date)} · ${esc(foods.find(f=>f.id===m.foodId)?.name||'食物')}</option>`).join('')}</select></div>`;showForm('记录食物',fields,async d=>{const f=foods.find(x=>x.id===d.foodId);if(!f)throw new Error('请选择有效食物');await repo.put('meals',{id:record?.id||uid(),date:d.date,meal:d.meal,foodId:d.foodId,grams:+d.grams});});}
function editFood(){const fields=field('食物名称','name','','text','required')+field('热量 kcal / 100g','kcal','','number','min="0" step="0.1" required')+field('蛋白质 g / 100g','protein','','number','min="0" step="0.1" required')+field('碳水 g / 100g','carbs','','number','min="0" step="0.1" required')+field('脂肪 g / 100g','fat','','number','min="0" step="0.1" required')+field('来源或说明','source','用户录入，待核对');showForm('新增自定义食物',fields,async d=>repo.put('foods',{id:uid(),...d,kcal:+d.kcal,protein:+d.protein,carbs:+d.carbs,fat:+d.fat,custom:true}));}
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function backup(){const data={format:'FitOS-backup',version:1,exportedAt:new Date().toISOString(),tables:{}};for(const t of TABLES)data.tables[t]=await repo.all(t);download(`fitos-backup-${today()}.json`,JSON.stringify(data,null,2),'application/json');toast('备份已生成（不含 AI 密钥）');}
function csvEscape(x){const s=String(x??'');return `"${s.replaceAll('"','""')}"`;}
function downloadCSV(name,headers,rows){const content='\ufeff'+[headers,...rows].map(r=>r.map(csvEscape).join(',')).join('\r\n');download(`fitos-${name}-${today()}.csv`,content,'text/csv;charset=utf-8');}
async function csvMenu(){const [m,s,meals,foods]=await Promise.all(['measurements','sessions','meals','foods'].map(t=>repo.all(t)));const choice=prompt('输入导出类型：body（身体记录）、workouts（训练历史）、sets（训练组明细）、meals（饮食明细）、nutrition（每日营养汇总）');if(choice==='body')downloadCSV('body',['date','weight_kg','body_fat_pct','waist_cm','hip_cm','note'],m.map(x=>[x.date,x.weight,x.bodyFat,x.waist,x.hip,x.note]));else if(choice==='workouts')downloadCSV('workouts',['date','name','status','duration_min','exercise_count','volume_kg'],s.map(x=>[x.date,x.name,x.status,x.duration,x.exerciseCount,volume(x)]));else if(choice==='sets')downloadCSV('sets',['date','workout','exercise','set_number','type','weight_kg','reps','rpe'],s.flatMap(w=>w.exercises.flatMap(e=>e.sets.map((z,i)=>[w.date,w.name,e.name,i+1,z.type,z.weight,z.reps,z.rpe]))));else if(choice==='meals')downloadCSV('meals',['date','meal','food','grams','kcal','protein_g','carbs_g','fat_g'],meals.map(m=>{const f=foods.find(x=>x.id===m.foodId);return[m.date,m.meal,f?.name,m.grams,...['kcal','protein','carbs','fat'].map(k=>f?f[k]*m.grams/100:'')]}));else if(choice==='nutrition'){const days=[...new Set(meals.map(x=>x.date))].sort();downloadCSV('nutrition',['date','kcal','protein_g','carbs_g','fat_g'],days.map(day=>{const sum=meals.filter(m=>m.date===day).reduce((a,m)=>{const f=foods.find(x=>x.id===m.foodId);if(f)for(const k of ['kcal','protein','carbs','fat'])a[k]+=f[k]*m.grams/100;return a;},{kcal:0,protein:0,carbs:0,fat:0});return[day,...Object.values(sum)]}));}else toast('没有导出：输入类型不匹配');}
function validBackup(x){if(!x||x.format!=='FitOS-backup'||x.version!==1||!x.tables||typeof x.tables!=='object')throw Error('文件格式或版本无效');for(const t of TABLES)if(!Array.isArray(x.tables[t]))throw Error(`缺少数据表：${t}`);for(const t of TABLES)for(const r of x.tables[t])if(!r||typeof r.id!=='string')throw Error(`${t} 中存在无效记录`);for(const s of x.tables.sessions){if(!Array.isArray(s.exercises))throw Error('训练记录结构无效');}return true;}
async function restoreFile(file){const text=await file.text(),data=JSON.parse(text);validBackup(data);const counts=TABLES.map(t=>`${t}: ${data.tables[t].length}`).join('\n');const mode=prompt(`备份校验通过。\n${counts}\n\n输入 replace 完全恢复，输入 merge 按稳定 ID 合并。其他输入取消。`);if(!['replace','merge'].includes(mode))return;const current={};if(mode==='merge')for(const t of TABLES)current[t]=await repo.all(t);const final={};for(const t of TABLES){const incoming=data.tables[t];final[t]=mode==='merge'?[...new Map([...(current[t]||[]),...incoming].map(r=>[r.id,r])).values()]:incoming;}if(mode==='replace'&&!confirm('完全恢复将替换当前数据。建议先导出当前备份。继续吗？'))return;
 // Atomic transaction: validate before opening, then clear and repopulate all stores together.
 await new Promise((resolve,reject)=>{const tx=db.transaction(TABLES,'readwrite');for(const t of TABLES){const store=tx.objectStore(t);if(mode==='replace')store.clear();for(const row of final[t])store.put(row);}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('恢复事务已回滚'));});toast('数据恢复完成');navigate();}
async function clearData(){if(!confirm('将永久清空 FitOS 全部本地数据。建议先导出 JSON 备份。继续？'))return;if(!confirm('再次确认：你确定清空本设备上的 FitOS 数据吗？'))return;for(const t of TABLES)await repo.clear(t);sessionStorage.removeItem('fitos-ai-key');activeSession=null;toast('本地 FitOS 数据已清空');location.hash='#home';navigate();}
function toggleTheme(){document.body.classList.toggle('light');localStorage.setItem('fitos-theme',document.body.classList.contains('light')?'light':'dark');}
async function testAI(){const settings=(await repo.all('settings')).find(x=>x.id==='ai'),key=sessionStorage.getItem('fitos-ai-key');if(!settings||!key)return toast('请先填写服务商配置和本次会话 API Key');try{const url=`${settings.baseUrl}/chat/completions`;const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model:settings.model,messages:[{role:'user',content:'Reply with OK.'}],max_tokens:10})});if(!response.ok)throw new Error(response.status===401?'API Key 无效或无权限':response.status===404?'端点或模型可能不正确':`HTTP ${response.status}`);toast('连接成功');}catch(e){toast(e.name==='TypeError'?'浏览器无法访问服务商，可能是网络或 CORS 限制':`连接失败：${e.message}`);}}
async function aiSuggestion(kind){const settings=(await repo.all('settings')).find(x=>x.id==='ai'),key=sessionStorage.getItem('fitos-ai-key');if(!settings||!key)return toast('请在 AI 页面配置服务商与本次会话密钥');const [p,g,m,s]=await Promise.all(['profile','goals','measurements','sessions'].map(t=>repo.all(t)));const context={profile:p[0]?{nickname:p[0].nickname,experience:p[0].experience,goalType:p[0].goalType,height:p[0].height}:null,goal:g.find(x=>x.status==='active')?{name:g.find(x=>x.status==='active').name,type:g.find(x=>x.status==='active').type,target:g.find(x=>x.status==='active').target}:null,recentMeasurements:m.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),recentCompletedWorkouts:s.filter(x=>x.status==='completed').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(x=>({date:x.date,name:x.name,exercises:x.exercises.map(e=>({name:e.name,sets:e.sets.filter(z=>z.done).map(z=>({weight:z.weight,reps:z.reps}))}))}))};const task={ 'coach-plan':'请根据输入事实给一份保守、可调整的商业健身房一周训练建议。缺少数据时指出；不要假设伤病或虚构历史。', 'coach-meal':'请给出一日饮食建议，标注估算值；如缺少身高、体重等，不要声称精确能量需求。','coach-review':'请基于实际记录复盘，指出数据不足和不确定性，不要把建议当医疗诊断。'}[kind];try{const response=await fetch(`${settings.baseUrl}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model:settings.model,messages:[{role:'system',content:`你是 FitOS 的谨慎健身助手。只能基于输入事实回答，区分事实和建议；记录不足明确说明。不要诊断疾病，不要虚构数据。`},{role:'user',content:`${task}\n用户数据 JSON：${JSON.stringify(context)}`}],temperature:.4})});if(!response.ok)throw Error(`HTTP ${response.status}`);const json=await response.json(),text=json.choices?.[0]?.message?.content;if(!text)throw Error('响应内容为空');$('#ai-output').innerHTML=`<div class="banner"><strong>AI 建议预览</strong> · 内容由服务商生成，请核对后自行决定。</div><pre style="white-space:pre-wrap;font:12px/1.8 inherit;color:var(--text)">${esc(text)}</pre>`;}catch(e){toast(e.name==='TypeError'?'AI 请求失败：网络不可用或浏览器 CORS 限制':`AI 请求失败：${e.message}`);}}
$('#restore-file').addEventListener('change',async e=>{try{if(e.target.files[0])await restoreFile(e.target.files[0]);}catch(err){toast(`恢复失败，现有数据未改动：${err.message}`);}finally{e.target.value='';}});
$('#theme-toggle').onclick=toggleTheme;$('#mobile-menu').onclick=()=>{$('#dialog-content').innerHTML=`<h2>FitOS 导航</h2><div class="list">${nav.map(([id,label])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}" style="display:flex"><span class="nav-icon">${icons[id]}</span>${label}</a>`).join('')}</div>`;$('#dialog').showModal();$('#dialog-content').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#dialog').close());};$('#profile-shortcut').onclick=()=>{location.hash='#profile';};
window.addEventListener('hashchange',navigate);
async function init(){try{db=await openDB();await seed();const active=(await repo.all('sessions')).find(x=>x.status==='in-progress');if(active)activeSession={id:active.id};if(localStorage.getItem('fitos-theme')==='light')document.body.classList.add('light');if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});$('#dialog .dialog-close').onclick=()=>$('#dialog').close();navigate();}catch(e){document.body.innerHTML=`<main style="padding:24px;font:14px sans-serif"><h1>FitOS 本地数据库无法启动</h1><p>建议使用 HTTPS 或 localhost 访问，并检查浏览器是否允许 IndexedDB。</p><pre>${esc(e.message)}</pre></main>`;}}
init();
